using UnityEngine;

/// <summary>
/// Plain reference holder for Runner's mobile controls PREFAB (Assets/_Project/Prefabs/UI/
/// MobileControls.prefab, generated by Tools > MusicGame > UI > Build All UI Prefabs). The prefab root is
/// the whole stretched layer; MobileControlsController only gates its visibility and initializes the
/// joystick (VirtualJoystick's drag state is runtime-only). TouchJumpButton/TouchCrouchButton already
/// sit on their buttons in the prefab and need no wiring.
/// </summary>
public class MobileControlsView : MonoBehaviour
{
    public VirtualJoystick   joystick;
    public RectTransform     joystickBackground;
    public RectTransform     joystickHandle;
    public TouchJumpButton   jumpButton;
    public TouchCrouchButton crouchButton;
}
